patch:
diff --git a/py/compile.c b/py/compile.c
index 1234567..abcdefg 100644
--- a/py/compile.c
+++ b/py/compile.c
@@ -1234,6 +1234,10 @@ STATIC void compile_try_except(compile_t *comp, mp_parse_node_struct_t *pns) {
         }
     }

+    // If the try block has a return, we need to ensure the finally block is executed.
+    // In MicroPython, if the try block returns, the finally block is executed before the return.
+    // However, if the finally block also returns, the return value from the try block is lost.
+    // This is consistent with CPython behavior.
     // Generate code for the finally block.
     compile_node(comp, pns->nodes[2]);
